import{_ as o,l as i,o as e,c as s,v as t,p as n,x as r,d,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"Deja Vu 上下文稀疏","description":"","frontmatter":{"title":"Deja Vu 上下文稀疏","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/deja-vu-sparsity.md","filePath":"llm/deja-vu-sparsity.md","lastUpdated":1789023840000}'),u={name:"llm/deja-vu-sparsity.md"};function h(m,a,c,_,A,f){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="deja-vu-上下文稀疏" tabindex="-1">Deja Vu 上下文稀疏 <a class="header-anchor" href="#deja-vu-上下文稀疏" aria-label="Permalink to &quot;Deja Vu 上下文稀疏&quot;">​</a></h1><div class="epigraph"><p>不必把激活函数改成 ReLU：用一个小预测器，根据当前上下文估计哪些 MLP 神经元、哪些注意力头会真被用到，其余跳过。</p><footer>—— Liu et al., Deja Vu: Contextual Sparsity for Efficient LLMs at Inference Time, ICML 2023</footer></div><p><a href="/llm/activation-sparsity">上一课</a> 靠 ReLU 把零写进前向。本课面向已经训好的 GLU Transformer：稀疏是<strong>上下文相关的预测掩码</strong>，不是函数图像上的精确零。缺口是：近似「这个 token 不需要整层容量」，而又不引入 <a href="/llm/moe-routing">MoE 路由</a> 那套专家并行。后课把头的删除从动态预测收成静态剪枝。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LLM 一层的 MLP 通道与注意力头对单个 token 贡献极不均——头功能分化课已经见过静态版。Deja Vu 问的是动态版：给定截至现在的隐状态，能否用远小于原层的代价，预测一张二值掩码，只跑子集，输出仍接近稠密层。预测错的代价是质量；预测本身的代价必须远小于省下的 GEMM，否则是净亏。</p><p>这与 MoE 的差别：MoE 的专家是预训练就切开的参数块，门是模型的一部分；Deja Vu 的预测器是推理期外挂，参数仍是原来那套稠密权重，只是有的行本次不乘。不能把两者的稀疏度表直接对比。</p><p><span class="marginnote">Contextual sparsity 的「上下文」指当前序列的隐状态，不是检索系统的文档上下文。不要接到 RAG 课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对 MLP：用低秩或小 MLP 吃入当前 \\(x\\)（或一层输入），输出通道级分数，阈值化得到保留集，只乘对应的 \\(W_\\mathrm{up}\\)/\\(W_\\mathrm{down}\\) 切片。对注意力：预测哪些头保留，只算那些头的 QKV 与 SDPA。预测器在校准或短微调里拟合稠密模型的「哪个通道激活大 / 哪头输出能量大」，推理冻结。</p><p>阈值是延迟旋钮：紧则快、质量掉。应在分能力集上扫，而不是只看平均 PPL。与 2:4 不同，掩码不规则，加速依赖「按保留通道做瘦 GEMM」的实现，保留集过碎会退化成 gather。</p>',10)),(e(),n(p,null,{default:r(()=>[E(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%BD%93%E5%89%8D%E9%9A%90%E7%8A%B6%E6%80%81%22%5D%20--%3E%20P%5B%22%E5%B0%8F%E9%A2%84%E6%B5%8B%E5%99%A8%22%5D%0A%20%20P%20--%3E%20M%5B%22%E9%80%9A%E9%81%93%20%2F%20%E5%A4%B4%E6%8E%A9%E7%A0%81%22%5D%0A%20%20M%20--%3E%20THIN%5B%22%E5%8F%AA%E8%B7%91%E5%AD%90%E9%9B%86%20GEMM%22%5D%0A%20%20DENSE%5B%22%E7%A8%A0%E5%AF%86%E6%9D%83%E9%87%8D%E4%BB%8D%E5%9C%A8%22%5D%20--%3E%20THIN%0A%20%20THIN%20--%3E%20Y%5B%22%E8%BF%91%E4%BC%BC%E5%B1%82%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>假设层计算对单个 token 是低维的：大部分通道近零或可被其它通道替代。预测器学的是这条低维支撑随上下文如何移动。它比 ReLU 更通用（GLU 也能近似稀疏），但有近似误差：预测器看不到未来 token，decode 每步重预测，误差可累积。Prefill 一次预测整段则更稳，却与真实逐步生成不完全一致。</p><p>负载没有 MoE 那种专家均衡问题，但有「预测器总选同一批通道」的退化：等于静态剪枝却还在付预测器。应监控保留集的熵与 Jaccard，避免假动态。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要在预测器成本接近原层时还宣称稀疏。不要与权重 2:4 连乘加速比。训练期一般仍稠密，只在推理开预测器——训推不一致是税，长链推理更敏感。下一课把「头可以少」做成静态事实：Michel 的剪头，不再每步预测。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Deja Vu：推理期预测 MLP 通道与注意力头的上下文掩码，权重要稠密。</li><li>不是 MoE：无专家切分，无 All-to-All。</li><li>预测器必须远便宜于省下的 GEMM；掩码过碎则无核。</li><li>监控假动态：保留集若塌成固定子集，应改静剪。</li><li>出处：Liu et al., ICML 2023。</li></ul>',7))])}const B=o(u,[["render",h]]);export{D as __pageData,B as default};
